replacements.new:
// VeltOS: several windows of one app look like a stack of buttons,
// as on Windows 11: a second plate peeks out on the right while
// the button is pointed at or active.
Rectangle {
    anchors.fill: frame
    anchors.leftMargin: 5
    anchors.rightMargin: -3
    anchors.topMargin: 5
    anchors.bottomMargin: 5
    radius: 5
    visible: !task.inPopup && model.IsGroupParent === true
             && (task.highlighted || model.IsActive === true)
    color: Qt.alpha(Kirigami.Theme.textColor, 0.05)
    border.width: 1
    border.color: Qt.alpha(Kirigami.Theme.textColor, 0.10)
}

KSvg.FrameSvgItem {
    id: frame
